import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.BIas3y6W.js";const g=JSON.parse('{"title":"Week 14 — Security & Review","description":"","frontmatter":{"source":"weeks/14-security-and-review/README.md"},"headers":[],"relativePath":"weeks/14-security-and-review/index.md","filePath":"weeks/14-security-and-review/index.md"}'),s={name:"weeks/14-security-and-review/index.md"};function n(i,e,h,l,d,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="week-14--security--review" tabindex="-1">Week 14 — Security &amp; Review <a class="header-anchor" href="#week-14--security--review" aria-label="Permalink to &quot;Week 14 — Security &amp; Review&quot;">​</a></h1><blockquote><p>Passing tests is not a security check. This week you sweep your capstone for the risks beyond the database, change it with the AI switched off, and let a classmate review it and try to change it.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before Studio A</strong> (30 min at most)</td><td>Read this page and case 15, book oral walkthrough 3, agree which pull request your partner reviews, commit everything. See <a href="#before-class">Before class</a></td></tr><tr><td><strong>Studio A</strong></td><td>Talk: cross-site scripting, secrets in old commits, packages, prompt injection and the lethal trifecta, this year&#39;s cases · the instructor&#39;s 7-minute prompt-injection demo · security sweep · a one-paragraph threat model · exit ticket</td></tr><tr><td><strong>Studio B</strong></td><td>Show and tell · <strong>AI-off maintenance task</strong> on your own capstone (🔴 AI off, 30 min) · peer review as a pull-request review (🔴 AI off) · project time: compare with an AI review</td></tr><tr><td><strong>Due before next week&#39;s Studio A</strong></td><td>Default 11:59 pm the night before. <strong>Milestone 2</strong>: <code>SECURITY_CHECKLIST.md</code> with evidence and a threat model · your written peer review and your response to the review you received, both on Canvas · the handoff test, noted in <code>PROMPTS.md</code> · reflection on Canvas · production URL plus a screenshot. <strong>Oral walkthrough 3</strong> done this week</td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: explaining sweep results, fixing what the sweep or review found, the AI review you compare with your own, the handoff tester&#39;s agent (approvals on) · 🟡 AI limited: your threat model (you write it; the AI may point out misuses you missed) · 🔴 AI off: the maintenance task, your pull-request review and written review, oral walkthrough 3, the reflection, the exit ticket</td></tr><tr><td><strong>Must read</strong></td><td>README (this page), <a href="./lab.html">Week 14 lab — Sweep, maintain, review</a>, <a href="./homework.html">Week 14 homework — Milestone 2: secure it, review it, hand it off</a></td></tr><tr><td><strong>Look up when needed</strong></td><td><a href="./../../templates/SECURITY_CHECKLIST.html">SECURITY_CHECKLIST.md template</a> · <a href="./../../templates/CODE_REVIEW.html">CODE_REVIEW.md template</a> · <a href="./../../assessment/oral-walkthroughs.html#what-to-expect">Oral walkthroughs: what to expect</a> · <a href="./../../resources/troubleshooting.html#i-committed-a-secret">Troubleshooting: I committed a secret</a> · <a href="https://github.com/Boyu-Zhang-UOI/vc101-injection-demo" target="_blank" rel="noreferrer">Prompt-injection demo kit</a> · <a href="./../../resources/case-studies.html">Case Studies</a> · <a href="./../../resources/glossary.html">Glossary</a></td></tr><tr><td><strong>Minimum to keep up</strong></td><td>Milestone 2 in place: every chosen feature type at least roughly working at the production URL, <code>SECURITY_CHECKLIST.md</code> with evidence, and walkthrough 3 done. Week 15 polishes and ships what you have</td></tr><tr><td><strong>Time</strong></td><td>Studios 2.5 h · outside about 6 h: prep 30 min, homework about 5.5 h, plus a 15-minute walkthrough slot if yours is by appointment</td></tr></tbody></table><p>Canvas is the course&#39;s learning management system. Graded personal writing (the written review, your response to the review you received, your reflection) goes there, never in a repo.</p><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Find and fix <strong>cross-site scripting (XSS)</strong> in your own pages, and explain why <code>textContent</code> is safe where <code>innerHTML</code> isn&#39;t.</li><li>Sweep your capstone for secrets in your files <strong>and git history</strong>, risky packages and CDN imports, and XSS, with one line of evidence each.</li><li>Explain <strong>prompt injection</strong> and the <strong>lethal trifecta</strong>, and say which parts of it your own agent setup has.</li><li>Write a one-paragraph <strong>threat model</strong> of one feature: who could misuse it, how, and what stops them.</li><li>Change your own code with the AI switched off.</li><li>Review a classmate&#39;s pull request as a human, compare it with an AI review, respond to the review you received, and hand your project off so someone else can change it.</li></ol><h2 id="before-class" tabindex="-1">Before class <a class="header-anchor" href="#before-class" aria-label="Permalink to &quot;Before class&quot;">​</a></h2><p>Before Studio A (30 minutes at most):</p><ul><li>☐ Read this page, and <a href="./../../resources/case-studies.html#15-malware-that-hunts-for-ai-keys">case 15: Malware that hunts for AI keys</a>.</li><li>☐ Book your <strong>oral walkthrough 3</strong> slot on Canvas: in this week&#39;s studios or an office-hour slot this week (<a href="./../../assessment/oral-walkthroughs.html#what-to-expect">what to expect</a>).</li><li>☐ Agree with your review partner (your instructor pairs you) which of your pull requests they&#39;ll review: your week-13 data feature is ideal, a week-12 one works too.</li><li>☐ Commit and push everything, so <code>git status</code> shows nothing to commit. The maintenance task starts from a clean tree.</li></ul><h2 id="studio-agenda" tabindex="-1">Studio agenda <a class="header-anchor" href="#studio-agenda" aria-label="Permalink to &quot;Studio agenda&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Studio</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Studio A — Learn &amp; build</strong></td><td>Recap · talk (<a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-14.html" target="_blank" rel="noreferrer">slides</a>) · the 7-minute prompt-injection demo · <a href="./lab.html#studio-a--sweep-and-threat-model-75-min">security sweep and threat model</a> · exit ticket · walkthrough 3 slots run alongside the sweep</td></tr><tr><td><strong>Studio B — Workshop</strong></td><td>Show and tell · <a href="./lab.html#studio-b--maintain-and-review-75-min">AI-off maintenance task and pull-request review</a> · project time: compare with an AI review · walkthrough 3 slots</td></tr></tbody></table><h2 id="materials" tabindex="-1">Materials <a class="header-anchor" href="#materials" aria-label="Permalink to &quot;Materials&quot;">​</a></h2><ul><li><a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-14.html" target="_blank" rel="noreferrer">Slides</a> and <a href="./lab.html">lab</a>, with Core and If time parts</li><li><a href="./homework.html">Homework</a>: Milestone 2, the security checklist, the review, the handoff test, walkthrough 3</li><li><a href="https://github.com/Boyu-Zhang-UOI/vc101-injection-demo" target="_blank" rel="noreferrer">Prompt-injection demo kit</a>: optional, to try the instructor&#39;s demo yourself in a fresh Codespace</li><li>Templates: <a href="./../../templates/SECURITY_CHECKLIST.html">SECURITY_CHECKLIST.md template</a>, <a href="./../../templates/CODE_REVIEW.html">CODE_REVIEW.md template</a></li></ul><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><p><strong>Passing tests is not a security check.</strong> Given 186 real vulnerabilities rewritten as feature requests, a frontier model wrote working code 93.5% of the time but working <strong>and secure</strong> code only 54.8% of the time (<a href="https://semgrep.dev/blog/2026/claude-opus-5-5-susvibes-benchmark" target="_blank" rel="noreferrer">Semgrep</a>). Last week you tested who can read and change your data. This week you check the rest.</p><p><strong>Cross-site scripting.</strong> <a href="./../../resources/glossary.html#xss">XSS</a> happens when text a user typed is put on the page with <code>innerHTML</code> and runs as code in other visitors&#39; browsers. Use <code>textContent</code>, which always shows text as text (<a href="./../../resources/glossary.html#innerhtml-and-textcontent">innerHTML and textContent</a>). If you&#39;ve met SQL injection, it&#39;s the same mistake: data treated as code. In 2026 tests, only 15% of AI code samples defended against it (<a href="https://www.veracode.com/blog/spring-2026-genai-code-security/" target="_blank" rel="noreferrer">Veracode</a>).</p><p><strong>Secrets in old commits.</strong> Deleting a key from today&#39;s file doesn&#39;t remove it from git history, and anyone can read a public repo&#39;s history. The course&#39;s secret scan (<code>npm run check:secrets</code>) reads the whole history. A key found there must be <strong>revoked and replaced</strong>; rewriting history isn&#39;t enough.</p><p><strong>Packages.</strong> Installing a package runs a stranger&#39;s code. <a href="./../../resources/glossary.html#slopsquatting">Slopsquatting</a> is when an attacker registers a name that AI models tend to invent (<a href="./../../resources/case-studies.html#10-slopsquatting-the-packages-that-dont-exist">case 10</a>). Real packages get hijacked too: in October 2026 a compromised npm release stole <code>.env</code> files and <code>.claude</code> and MCP settings on install, and a poisoned Python package stole AI provider keys (<a href="./../../resources/case-studies.html#15-malware-that-hunts-for-ai-keys">case 15</a>). <code>pip install</code> runs code just like <code>npm install</code>. Install only what the plan named, check it&#39;s the one you meant, and pin the version.</p><p><strong>No attacker needed.</strong> Helpful agents created public repositories that exposed more than 13,000 internal screenshots (PixelLeak, <a href="https://thehackernews.com/2026/09/ai-coding-agents-exposed-13000-internal.html" target="_blank" rel="noreferrer">The Hacker News</a>), and an agent used a token from an unrelated file to delete a production database and its backups in about nine seconds (PocketOS, <a href="https://ia.acs.org.au/article/2026/gone-in-9-seconds--ai-agent-deletes-company-database.html" target="_blank" rel="noreferrer">Information Age</a>). So agents don&#39;t publish without your approval, and keys stay out of their reach (<a href="./../../setup/safety-contract.html">safety contract</a>, rules 4 and 9).</p><p><strong>Prompt injection.</strong> <a href="./../../resources/glossary.html#prompt-injection">Prompt injection</a> is when text an agent reads (a file, a web page, an issue) gives it orders. The <a href="./../../resources/glossary.html#lethal-trifecta">lethal trifecta</a> is private data + untrusted content + a way to send data out (<a href="https://simonwillison.net/2025/Jun/16/the-lethal-trifecta/" target="_blank" rel="noreferrer">Willison</a>); Meta&#39;s <a href="./../../resources/glossary.html#rule-of-two">Rule of Two</a> says an agent should hold at most two of them without a human approving (<a href="https://ai.meta.com/blog/practical-ai-agent-security/" target="_blank" rel="noreferrer">Meta</a>). <code>AGENTS.md</code> can tell an agent to ignore such text, but it&#39;s advice, not a lock.</p><p><strong>A threat model in one paragraph.</strong> Say what &quot;unsafe&quot; would mean before you check: who could misuse a feature, how, and what stops them. It&#39;s the short form of the questions professionals ask: what are we working on, what can go wrong, what are we going to do about it, and did we do a good enough job (<a href="https://www.threatmodelingmanifesto.org/" target="_blank" rel="noreferrer">Threat Modeling Manifesto</a>).</p><p><strong>Can you maintain it without the AI?</strong> In one study, 77% of students who used AI without restrictions failed a 30-minute maintenance task with the AI switched off, against 39% of those who had to explain the code first (<a href="https://arxiv.org/abs/2602.20206" target="_blank" rel="noreferrer">Sankaranarayanan</a>). Experience doesn&#39;t exempt you: experienced developers were 19% slower with AI while believing they were faster (<a href="./../../resources/case-studies.html#11-metr-feeling-faster-vs-being-faster">case 11, METR</a>). Studio B&#39;s maintenance task is graded on effort, not on finishing.</p><p><strong>Humans and AI both review.</strong> An AI reviewer is fast and tireless, but it misses the goal and raises false alarms. A human reviewer knows what the app is for. You review a classmate&#39;s <a href="./../../resources/glossary.html#pull-request">pull request</a> yourself, then compare with an AI review. The <strong>handoff test</strong> asks the harder question: can someone else change your app from your <code>README.md</code> and <code>AGENTS.md</code> alone?</p><h2 id="understanding-check" tabindex="-1">Understanding check <a class="header-anchor" href="#understanding-check" aria-label="Permalink to &quot;Understanding check&quot;">​</a></h2><ul><li>The week 14 exit ticket comes at the <strong>end of Studio A</strong>, with AI off (🔴), because Studio B is full of AI-off work. You&#39;ll explain prompt injection and what protects you, describe one vulnerability you found or fixed, and answer one question from memory about your week-12 pull request. Graded on completion, not correctness.</li><li><strong>Oral walkthrough 3</strong> (10 minutes, 🔴 AI off) runs this week, in a studio slot or an office-hour slot: explain where authorization is enforced, find and fix a planted bug, spot a committed secret in a sample diff, and explain one of your tests (<a href="./../../assessment/oral-walkthroughs.html#what-to-expect">what to expect</a>). It&#39;s the last walkthrough: week 15 has none.</li></ul><h2 id="homework" tabindex="-1">Homework <a class="header-anchor" href="#homework" aria-label="Permalink to &quot;Homework&quot;">​</a></h2><p><a href="./homework.html">Homework</a>: reach <strong>Milestone 2</strong>: the checklist and threat model, the written review and your response to the one you received, the handoff test, walkthrough 3 and your reflection. About 5.5 hours.</p><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><ul><li><strong>Codespaces quota gone:</strong> do the maintenance task in github.dev and check it on your Vercel preview; run the sweep&#39;s commands with a <a href="./../../setup/local-setup.html">local setup</a> or in office hours. The review needs only the GitHub website.</li><li><strong>Copilot credits gone:</strong> the review, the maintenance task and the sweep need no AI. For the AI half of the review, use any free chat assistant with the diff pasted in (<a href="./../../resources/troubleshooting.html#i-ran-out-of-free-credits">I ran out of free credits</a>).</li><li><strong><code>npm audit</code> says <code>ENOLOCK</code>:</strong> run <code>npm install</code> once and commit the <code>package-lock.json</code> it creates (lab Part A1).</li><li><strong>No partner today:</strong> your instructor gives you a change-request card and a practice pull request with known issues to review (<a href="./../../resources/self-paced.html">Self-paced path</a>).</li><li><strong>Your capstone is behind:</strong> sweep your week-9 micro-app instead; the maintenance cards are small enough for whatever your capstone has.</li><li><strong>Missed your walkthrough slot</strong> for illness or another recognized reason? Tell your instructor: it&#39;s rescheduled without penalty.</li></ul><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>Protect your <code>main</code> branch so it only accepts pull requests with a green test run (homework stretch).</li><li>Read one 2026 incident in full from <a href="./../../resources/case-studies.html">Case Studies</a> and add a one-line lesson to your <code>SECURITY_CHECKLIST.md</code>.</li><li>Try the <a href="https://github.com/Boyu-Zhang-UOI/vc101-injection-demo" target="_blank" rel="noreferrer">Prompt-injection demo kit</a> yourself in a fresh Codespace, never in your capstone.</li><li>Extend your threat model with STRIDE, the six-category checklist many teams use (<a href="https://cheatsheetseries.owasp.org/cheatsheets/Threat_Modeling_Cheat_Sheet.html" target="_blank" rel="noreferrer">OWASP Threat Modeling Cheat Sheet</a>).</li></ul>',33)])])}const p=t(s,[["render",n]]);export{g as __pageData,p as default};
